"""Utility helpers shared across pandarallel modules."""

from __future__ import annotations

from math import ceil
from typing import Any, Iterable, Sequence

import numpy as np
import pandas as pd


def coerce_worker_count(requested: int, total_units: int) -> int:
    requested = max(1, int(requested))
    total_units = max(1, int(total_units))
    return min(requested, total_units)


def chunk_slices(length: int, max_chunks: int) -> list[slice]:
    if length <= 0:
        return []

    chunks = coerce_worker_count(max_chunks, length)
    chunk_size = int(ceil(length / chunks))

    return [slice(start, min(length, start + chunk_size)) for start in range(0, length, chunk_size)]


def chunk_items[T](items: Sequence[T], max_chunks: int) -> list[list[T]]:
    if not items:
        return []

    chunks = coerce_worker_count(max_chunks, len(items))
    chunk_size = int(ceil(len(items) / chunks))
    return [list(items[start : start + chunk_size]) for start in range(0, len(items), chunk_size)]


def concat_axis0(results: Sequence[Any]) -> Any:
    if not results:
        raise ValueError("Cannot concatenate an empty result set.")
    if len(results) == 1:
        return results[0]
    return pd.concat(list(results), axis=0)


def combine_dataframe_apply_results(results: Sequence[Any], axis: int) -> Any:
    if not results:
        raise ValueError("Cannot combine an empty result set.")

    if len(results) == 1:
        return results[0]

    first = results[0]
    if isinstance(first, pd.DataFrame):
        concat_axis = 1 if axis == 0 else 0
        return pd.concat(list(results), axis=concat_axis)
    if isinstance(first, pd.Series):
        return pd.concat(list(results), axis=0)
    return list(results)


def slice_frame_or_series(obj: pd.DataFrame | pd.Series, item_slice: slice, axis: int = 0) -> pd.DataFrame | pd.Series:
    if axis == 0:
        return obj.iloc[item_slice]
    return obj.iloc[:, item_slice]


def concatenate_group_positions(group_items: Sequence[tuple[Any, Iterable[int]]]) -> np.ndarray:
    if not group_items:
        return np.array([], dtype=int)
    return np.concatenate([np.asarray(positions, dtype=int) for _, positions in group_items])


def extract_grouping_sources(groupings: Sequence[Any]) -> list[dict[str, Any]]:
    metadata: list[dict[str, Any]] = []
    for grouping in groupings:
        source = getattr(grouping, "_orig_grouper", None)
        if source is None:
            source = getattr(grouping, "grouping_vector")
        metadata.append(
            {
                "name": getattr(grouping, "name", None),
                "level": getattr(grouping, "level", None),
                "source": source,
            }
        )
    return metadata


def slice_grouping_source(source: Any, positions: np.ndarray, index: pd.Index, name: str | None = None) -> Any:
    if isinstance(source, pd.Series):
        return source.iloc[positions]
    if isinstance(source, pd.Index):
        return pd.Series(source.take(positions), index=index, name=name or source.name)

    values = np.asarray(source)[positions]
    return pd.Series(values, index=index, name=name)


def normalize_groupby_by(groupers: Sequence[Any]) -> Any:
    if len(groupers) == 1:
        return groupers[0]
    return list(groupers)

