"""Shared helpers for pandas-specific wrappers."""

from __future__ import annotations

from typing import Any

import pandas as pd

from pandarallel.utils import extract_grouping_sources, normalize_groupby_by, slice_grouping_source


def extract_groupby_metadata(groupby_obj: Any) -> dict[str, Any]:
    return {
        "as_index": getattr(groupby_obj, "as_index", True),
        "dropna": getattr(groupby_obj, "dropna", True),
        "group_keys": getattr(groupby_obj, "group_keys", True),
        "groupers": extract_grouping_sources(groupby_obj._grouper.groupings),
        "level": getattr(groupby_obj, "level", None),
        "observed": getattr(groupby_obj, "observed", False),
        "sort": getattr(groupby_obj, "sort", getattr(groupby_obj._grouper, "_sort", True)),
    }


def materialize_groupers(metadata: dict[str, Any], positions: Any, index: pd.Index) -> dict[str, Any]:
    prepared = dict(metadata)
    if metadata.get("level") is not None:
        return prepared

    groupers = []
    for grouper in metadata["groupers"]:
        groupers.append(
            slice_grouping_source(
                grouper["source"],
                positions,
                index,
                grouper.get("name"),
            )
        )
    prepared["groupers"] = groupers
    return prepared


def rebuild_groupby(obj: pd.DataFrame | pd.Series, metadata: dict[str, Any]) -> Any:
    kwargs = {
        "as_index": metadata["as_index"],
        "dropna": metadata["dropna"],
        "group_keys": metadata["group_keys"],
        "observed": metadata["observed"],
        "sort": metadata["sort"],
    }
    level = metadata.get("level")
    if level is not None:
        kwargs["level"] = level
    else:
        kwargs["by"] = normalize_groupby_by(metadata["groupers"])
    return obj.groupby(**kwargs)

