"""Minimal progress bar helpers used by parallel jobs."""

from __future__ import annotations

import os
import sys
import time
from dataclasses import dataclass


def _in_notebook() -> bool:
    try:
        from IPython import get_ipython  # type: ignore
    except Exception:
        return False

    shell = get_ipython()
    if shell is None:
        return False

    return shell.__class__.__name__ == "ZMQInteractiveShell"


class BaseProgressBar:
    def update(self, step: int = 1) -> None:
        raise NotImplementedError

    def close(self) -> None:
        raise NotImplementedError


class NullProgressBar(BaseProgressBar):
    def update(self, step: int = 1) -> None:
        return None

    def close(self) -> None:
        return None


@dataclass
class TerminalProgressBar(BaseProgressBar):
    total: int
    description: str = ""
    stream: object = sys.stderr
    width: int = 24
    refresh_interval: float = 0.1

    def __post_init__(self) -> None:
        self.current = 0
        self._last_render = 0.0
        self._isatty = bool(getattr(self.stream, "isatty", lambda: False)())
        self._render(force=True)

    def update(self, step: int = 1) -> None:
        self.current = min(self.total, self.current + step)
        self._render(force=self.current >= self.total)

    def close(self) -> None:
        self._render(force=True)
        if self.total:
            self._write(os.linesep)

    def _render(self, force: bool = False) -> None:
        now = time.monotonic()
        if not force and now - self._last_render < self.refresh_interval:
            return

        total = max(1, self.total)
        ratio = min(1.0, self.current / total)
        filled = int(self.width * ratio)
        bar = "#" * filled + "-" * (self.width - filled)
        message = f"{self.description} [{bar}] {ratio:6.1%} ({self.current}/{self.total})"

        if self._isatty:
            self._write("\r" + message)
        else:
            self._write(message + os.linesep)

        self._last_render = now

    def _write(self, message: str) -> None:
        self.stream.write(message)
        self.stream.flush()


class NotebookProgressBar(TerminalProgressBar):
    pass


def create_progress_bar(enabled: bool, total: int, description: str = "") -> BaseProgressBar:
    if not enabled or total <= 0:
        return NullProgressBar()
    if _in_notebook():
        return NotebookProgressBar(total=total, description=description)
    return TerminalProgressBar(total=total, description=description)

