"""Core configuration and execution engine for pandarallel."""

from __future__ import annotations

import logging
import multiprocessing as mp
import os
import tempfile
from concurrent.futures import ProcessPoolExecutor, as_completed
from dataclasses import dataclass
from typing import Any, Callable, Optional, Sequence
from warnings import warn

import dill
import psutil

from pandarallel.progress_bars import create_progress_bar

__version__ = "0.1.0"

MEMORY_FS_ROOT = os.environ.get("MEMORY_FS_ROOT", "/dev/shm")
NB_PHYSICAL_CORES = psutil.cpu_count(logical=False) or os.cpu_count() or 1


class ParallelTransportError(RuntimeError):
    """Raised when the requested transport backend cannot be used."""


class InvalidConfigurationError(ValueError):
    """Raised when the provided pandarallel configuration is invalid."""


@dataclass(frozen=True)
class ParallelConfig:
    nb_workers: int
    progress_bar: bool
    verbose: int
    use_memory_fs: bool
    transport: str
    memory_fs_root: str


def _build_logger() -> logging.Logger:
    logger = logging.getLogger("pandarallel")
    if not logger.handlers:
        handler = logging.StreamHandler()
        handler.setFormatter(logging.Formatter("[%(levelname)s] %(message)s"))
        logger.addHandler(handler)
    logger.propagate = False
    return logger


LOGGER = _build_logger()
_PATCHED = False


def _configure_logger(verbose: int) -> None:
    if verbose <= 0:
        LOGGER.setLevel(logging.CRITICAL + 1)
    elif verbose == 1:
        LOGGER.setLevel(logging.WARNING)
    else:
        LOGGER.setLevel(logging.INFO)


def is_memory_fs_available(root: str = MEMORY_FS_ROOT) -> bool:
    if os.name == "nt":
        return False
    if not os.path.isdir(root):
        return False
    if not os.access(root, os.R_OK | os.W_OK):
        return False

    try:
        file_descriptor, path = tempfile.mkstemp(prefix="pandarallel-probe-", dir=root)
    except OSError:
        return False

    os.close(file_descriptor)
    try:
        os.remove(path)
    except OSError:
        return False

    return True


def _resolve_transport(use_memory_fs: Optional[bool], root: str = MEMORY_FS_ROOT) -> tuple[bool, str]:
    available = is_memory_fs_available(root)
    if use_memory_fs is None:
        return available, "memory_fs" if available else "pipe"
    if use_memory_fs and not available:
        raise ParallelTransportError(
            f"Memory file system transport requested but unavailable at {root!r}."
        )
    return bool(use_memory_fs), "memory_fs" if use_memory_fs else "pipe"


def _default_config() -> ParallelConfig:
    use_memory_fs, transport = _resolve_transport(None, MEMORY_FS_ROOT)
    return ParallelConfig(
        nb_workers=NB_PHYSICAL_CORES,
        progress_bar=False,
        verbose=2,
        use_memory_fs=use_memory_fs,
        transport=transport,
        memory_fs_root=MEMORY_FS_ROOT,
    )


_ACTIVE_CONFIG = _default_config()
_configure_logger(_ACTIVE_CONFIG.verbose)


def get_config() -> ParallelConfig:
    return _ACTIVE_CONFIG


def _set_config(config: ParallelConfig) -> None:
    global _ACTIVE_CONFIG
    _ACTIVE_CONFIG = config
    _configure_logger(config.verbose)


def _mp_context() -> mp.context.BaseContext:
    if os.name == "nt":
        return mp.get_context("spawn")
    try:
        return mp.get_context("fork")
    except ValueError:
        return mp.get_context("spawn")


def _pack_job(runner: Callable[[Any], Any], payload: Any, config: ParallelConfig) -> dict[str, Any]:
    job = {"runner": dill.dumps(runner), "payload": dill.dumps(payload)}
    if config.transport == "memory_fs":
        file_descriptor, path = tempfile.mkstemp(
            prefix="pandarallel-job-",
            suffix=".bin",
            dir=config.memory_fs_root,
        )
        with os.fdopen(file_descriptor, "wb") as handle:
            dill.dump(job, handle)
        return {"path": path}
    return {"job": dill.dumps(job)}


def _load_packed_job(packed_job: dict[str, Any]) -> dict[str, Any]:
    if "path" in packed_job:
        path = packed_job["path"]
        with open(path, "rb") as handle:
            job = dill.load(handle)
        try:
            os.remove(path)
        except OSError:
            pass
        return job
    return dill.loads(packed_job["job"])


def _cleanup_packed_job(packed_job: dict[str, Any]) -> None:
    path = packed_job.get("path")
    if not path:
        return
    try:
        os.remove(path)
    except OSError:
        pass


def _execute_packed_job(packed_job: dict[str, Any]) -> Any:
    job = _load_packed_job(packed_job)
    runner = dill.loads(job["runner"])
    payload = dill.loads(job["payload"])
    return runner(payload)


def run_parallel_jobs(
    runner: Callable[[Any], Any],
    payloads: Sequence[Any],
    *,
    description: str,
) -> list[Any]:
    config = get_config()
    if not payloads:
        return []

    progress_bar = create_progress_bar(config.progress_bar, len(payloads), description)
    try:
        if config.nb_workers <= 1 or len(payloads) == 1:
            results: list[Any] = []
            for payload in payloads:
                results.append(runner(payload))
                progress_bar.update()
            return results

        workers = min(config.nb_workers, len(payloads))
        packed_jobs = [_pack_job(runner, payload, config) for payload in payloads]
        results: list[Any] = [None] * len(payloads)
        try:
            with ProcessPoolExecutor(max_workers=workers, mp_context=_mp_context()) as executor:
                future_to_index = {
                    executor.submit(_execute_packed_job, packed_job): index
                    for index, packed_job in enumerate(packed_jobs)
                }
                for future in as_completed(future_to_index):
                    index = future_to_index[future]
                    results[index] = future.result()
                    progress_bar.update()
        finally:
            for packed_job in packed_jobs:
                _cleanup_packed_job(packed_job)

        return results
    finally:
        progress_bar.close()


class pandarallel:
    @classmethod
    def initialize(
        cls,
        shm_size_mb: Any = None,
        nb_workers: int = NB_PHYSICAL_CORES,
        progress_bar: bool = False,
        verbose: int = 2,
        use_memory_fs: Optional[bool] = None,
    ) -> None:
        if shm_size_mb is not None:
            warn("`shm_size_mb` is deprecated and ignored.", DeprecationWarning, stacklevel=2)

        if nb_workers is None:
            nb_workers = NB_PHYSICAL_CORES
        if int(nb_workers) < 1:
            raise InvalidConfigurationError("`nb_workers` must be greater than or equal to 1.")
        if int(verbose) not in (0, 1, 2):
            raise InvalidConfigurationError("`verbose` must be one of 0, 1, or 2.")

        resolved_use_memory_fs, transport = _resolve_transport(use_memory_fs, MEMORY_FS_ROOT)
        config = ParallelConfig(
            nb_workers=int(nb_workers),
            progress_bar=bool(progress_bar),
            verbose=int(verbose),
            use_memory_fs=resolved_use_memory_fs,
            transport=transport,
            memory_fs_root=MEMORY_FS_ROOT,
        )
        _set_config(config)
        ensure_patched()
        LOGGER.info(
            "Initialized pandarallel with workers=%s, progress_bar=%s, transport=%s",
            config.nb_workers,
            config.progress_bar,
            config.transport,
        )


def initialize(*args: Any, **kwargs: Any) -> None:
    pandarallel.initialize(*args, **kwargs)


def ensure_patched() -> None:
    global _PATCHED
    if _PATCHED:
        return

    from pandarallel.data_types import register_parallel_methods

    register_parallel_methods()
    _PATCHED = True

