"""Parallel apply support for DataFrameGroupBy and SeriesGroupBy objects."""

from __future__ import annotations

from typing import Any

import dill
import pandas as pd

from pandarallel.core import get_config, run_parallel_jobs
from pandarallel.data_types.generic import extract_groupby_metadata, materialize_groupers, rebuild_groupby
from pandarallel.utils import chunk_items, concat_axis0, concatenate_group_positions


def _groupby_apply_runner(payload: dict[str, Any]) -> Any:
    function = dill.loads(payload["function"])
    grouped = rebuild_groupby(payload["object"], payload["metadata"])
    return grouped.apply(function, *payload["args"], **payload["kwargs"])


def parallel_apply(self: Any, func: Any, *args: Any, **kwargs: Any) -> Any:
    group_items = list(self.indices.items())
    if not group_items:
        return self.apply(func, *args, **kwargs)

    worker_count = min(get_config().nb_workers, len(group_items))
    metadata = extract_groupby_metadata(self)
    payloads = []
    for grouped_items in chunk_items(group_items, worker_count):
        positions = concatenate_group_positions(grouped_items)
        subset = self._selected_obj.iloc[positions]
        payloads.append(
            {
                "args": args,
                "function": dill.dumps(func),
                "kwargs": kwargs,
                "metadata": materialize_groupers(metadata, positions, subset.index),
                "object": subset,
            }
        )

    results = run_parallel_jobs(_groupby_apply_runner, payloads, description="GroupBy.apply")
    return concat_axis0(results)

"""Parallel operations for pandas DataFrame objects."""

from __future__ import annotations

from typing import Any

import dill
import pandas as pd

from pandarallel.core import get_config, run_parallel_jobs
from pandarallel.utils import chunk_slices, combine_dataframe_apply_results, concat_axis0, slice_frame_or_series


def _dataframe_apply_runner(payload: dict[str, Any]) -> Any:
    dataframe = payload["dataframe"]
    function = dill.loads(payload["function"])
    return dataframe.apply(
        function,
        axis=payload["axis"],
        raw=payload["raw"],
        result_type=payload["result_type"],
        args=payload["args"],
        **payload["kwargs"],
    )


def _dataframe_applymap_runner(payload: dict[str, Any]) -> pd.DataFrame:
    dataframe = payload["dataframe"]
    function = dill.loads(payload["function"])
    return dataframe.applymap(function, na_action=payload["na_action"], **payload["kwargs"])


def parallel_apply(
    self: pd.DataFrame,
    func: Any,
    axis: int | str = 0,
    raw: bool = False,
    result_type: str | None = None,
    args: tuple[Any, ...] = (),
    **kwargs: Any,
) -> Any:
    axis_number = self._get_axis_number(axis)
    split_axis = 1 if axis_number == 0 else 0
    length = self.shape[split_axis]
    if length == 0:
        return self.apply(func, axis=axis_number, raw=raw, result_type=result_type, args=args, **kwargs)

    worker_count = min(get_config().nb_workers, length)
    payloads = []
    for item_slice in chunk_slices(length, worker_count):
        payloads.append(
            {
                "axis": axis_number,
                "args": args,
                "dataframe": slice_frame_or_series(self, item_slice, axis=split_axis),
                "function": dill.dumps(func),
                "kwargs": kwargs,
                "raw": raw,
                "result_type": result_type,
            }
        )

    results = run_parallel_jobs(_dataframe_apply_runner, payloads, description="DataFrame.apply")
    return combine_dataframe_apply_results(results, axis_number)


def parallel_applymap(
    self: pd.DataFrame,
    func: Any,
    na_action: str | None = None,
    **kwargs: Any,
) -> pd.DataFrame:
    if len(self) == 0:
        return self.applymap(func, na_action=na_action, **kwargs)

    worker_count = min(get_config().nb_workers, len(self))
    payloads = []
    for item_slice in chunk_slices(len(self), worker_count):
        payloads.append(
            {
                "dataframe": slice_frame_or_series(self, item_slice, axis=0),
                "function": dill.dumps(func),
                "kwargs": kwargs,
                "na_action": na_action,
            }
        )

    results = run_parallel_jobs(_dataframe_applymap_runner, payloads, description="DataFrame.applymap")
    return concat_axis0(results)

