"""Parallel operations for pandas Series objects."""

from __future__ import annotations

from typing import Any

import dill
import pandas as pd

from pandarallel.core import get_config, run_parallel_jobs
from pandarallel.utils import chunk_slices, concat_axis0, slice_frame_or_series

_UNSET = object()


def _series_apply_runner(payload: dict[str, Any]) -> Any:
    series = payload["series"]
    function = dill.loads(payload["function"])
    apply_kwargs = {"args": payload["args"], **payload["kwargs"]}
    if payload["convert_dtype_provided"]:
        apply_kwargs["convert_dtype"] = payload["convert_dtype"]
    if payload["by_row_provided"]:
        apply_kwargs["by_row"] = payload["by_row"]

    try:
        return series.apply(function, **apply_kwargs)
    except TypeError:
        apply_kwargs.pop("by_row", None)
        return series.apply(function, **apply_kwargs)


def _series_map_runner(payload: dict[str, Any]) -> pd.Series:
    series = payload["series"]
    arg = dill.loads(payload["arg"])
    return series.map(arg, na_action=payload["na_action"])


def parallel_apply(
    self: pd.Series,
    func: Any,
    convert_dtype: Any = _UNSET,
    args: tuple[Any, ...] = (),
    by_row: Any = _UNSET,
    **kwargs: Any,
) -> Any:
    if len(self) == 0:
        return self.apply(func, args=args, **kwargs)

    worker_count = min(get_config().nb_workers, len(self))
    payloads = []
    for item_slice in chunk_slices(len(self), worker_count):
        payloads.append(
            {
                "args": args,
                "by_row": by_row,
                "by_row_provided": by_row is not _UNSET,
                "convert_dtype": None if convert_dtype is _UNSET else convert_dtype,
                "convert_dtype_provided": convert_dtype is not _UNSET,
                "function": dill.dumps(func),
                "kwargs": kwargs,
                "series": slice_frame_or_series(self, item_slice),
            }
        )

    results = run_parallel_jobs(_series_apply_runner, payloads, description="Series.apply")
    return concat_axis0(results)


def parallel_map(
    self: pd.Series,
    arg: Any,
    na_action: str | None = None,
) -> pd.Series:
    if len(self) == 0:
        return self.map(arg, na_action=na_action)

    worker_count = min(get_config().nb_workers, len(self))
    payloads = []
    for item_slice in chunk_slices(len(self), worker_count):
        payloads.append(
            {
                "arg": dill.dumps(arg),
                "na_action": na_action,
                "series": slice_frame_or_series(self, item_slice),
            }
        )

    results = run_parallel_jobs(_series_map_runner, payloads, description="Series.map")
    return concat_axis0(results)

