import numpy as np
import pandas as pd

from pandarallel import pandarallel


def _frame_row_sum(row: pd.Series) -> float:
    return float(row["a"] + row["b"])


def _scale(value: float) -> float:
    return value * 2


def _group_total(frame: pd.DataFrame) -> pd.DataFrame:
    return frame.assign(total=frame["b"] + frame["c"])


def _rolling_delta(window: pd.Series) -> float:
    return float(window.iloc[-1] - window.iloc[0])


def setup_module() -> None:
